// 打开新闻弹窗: 加载当日 news_digest.json + 上证分时序列(可分时则渲染迷你图,否则静态降级)。
async function openNewsDigestModal() {
  newsDigestModalEl().classList.remove("hidden");
  document.body.style.overflow = "hidden";
  const body = document.getElementById("news-digest-body");
  if (body) body.innerHTML = '<div class="news-empty">加载中…</div>';
  try {
    const raw = await fetchJSON("./data/news_digest.json");
    const all = (raw && Array.isArray(raw.news)) ? raw.news : [];
    const upcoming = (raw && Array.isArray(raw.upcoming)) ? raw.upcoming : [];
    _newsModalState = { all, news: all, upcoming, date: (raw && raw.date) || "", src: _newsModalState && _newsModalState.src ? _newsModalState.src : "all" };
  } catch (e) {
    _newsModalState = { all: [], upcoming: [], date: "", src: "all" };
    _newsModalState.err = String((e && e.message) || e);
  }
  // ④分时序列: 拉上证分时(有则迷你图示;失败/休市空则由静态降级补一句)。
  try {
    if (!_newsModalSparkCached) {
      const md = await fetchTencentMinute("sh");
      if (md && md.points && md.points.length) _newsModalSparkCached = md;
    }
  } catch (e2) { /* 分时不可得: 走静态降级 */ }
  try {
    if (!_newsModalSparkStatic) {
      const snap = await fetchJSON("./data/intraday_snapshot.json");
      const idx = (snap && Array.isArray(snap.indices)) ? (snap.indices.find((i) => i && i.name === "上证指数") || snap.indices[0]) : null;
      _newsModalSparkStatic = idx;
    }
  } catch (e3) { /* 静态降级数据不可得: 不显示分时区 */ }
  _renderNewsDigestBody();
  _startNewsDigestModalPoll(); // 2026-08-19 弹窗开着时每 5 分钟静默重拉原地更新(不重置滚动位置)
}

function closeNewsDigestModal() {
  const modal = document.getElementById("newsDigestModal");
  if (modal) modal.classList.add("hidden");
  document.body.style.overflow = "";
  _stopNewsDigestModalPoll(); // 2026-08-19 弹窗关闭即停轮询
}

// 分页器：与历史收盘分析同款（上一页/下一页 + 页码按钮 + 顶部 info 行）
function _renderDailyBriefPager(modal) {
  const { page, limit, total } = _dailyBriefState;
  const maxPage = Math.max(0, Math.ceil(total / limit) - 1);
  const pageCount = maxPage + 1;
  const info = modal.querySelector(".summary-history-info");
  info.textContent = total > 0 ? `共 ${total} 条记录 · 第 ${page + 1} / ${pageCount} 页` : "";
  const prev = modal.querySelector(".sh-prev");
  const next = modal.querySelector(".sh-next");
  prev.disabled = page <= 0;
  next.disabled = page >= maxPage;
  const pagesEl = modal.querySelector(".sh-pages");
  let btns = [];
  if (pageCount <= 7) {
    for (let i = 0; i < pageCount; i++) btns.push(i);
  } else {
    btns.push(0);
    if (page > 2) btns.push(-1);
    for (let i = Math.max(1, page - 1); i <= Math.min(pageCount - 2, page + 1); i++) btns.push(i);
    if (page < pageCount - 3) btns.push(-2);
    btns.push(pageCount - 1);
  }
  pagesEl.innerHTML = btns.map((i) =>
    i < 0
      ? '<span class="sh-ellipsis">…</span>'
      : `<button class="sh-page-btn${i === page ? " active" : ""}" data-page="${i}">${i + 1}</button>`
  ).join("");
  pagesEl.querySelectorAll(".sh-page-btn").forEach((b) => {
    b.addEventListener("click", () => {
      const p = +b.dataset.page;
      if (p !== _dailyBriefState.page) {
        _dailyBriefState.page = p;
        _loadDailyBriefPage();
      }
    });
  });
}

function openDailyBriefModal() {
  _dailyBriefState.page = 0;
  _dailyBriefState.total = 0;
  _dailyBriefState.cache = null;
  _dailyBriefModalEl().classList.remove("hidden");
  document.body.style.overflow = "hidden";
  _loadDailyBriefPage();
}

